"""Strict output schema validation."""


class SchemaError(Exception):
    pass


def chk_int(v, path):
    if type(v) is not int:
        raise SchemaError('%s: not int (%r %s)' % (path, v, type(v)))


def chk_bool(v, path):
    if type(v) is not bool:
        raise SchemaError('%s: not bool (%r)' % (path, v))


def chk_str(v, path):
    if type(v) is not str:
        raise SchemaError('%s: not str (%r)' % (path, v))


def chk_list(v, path):
    if type(v) is not list:
        raise SchemaError('%s: not list' % path)
    return v


def chk_dict(v, path, keys):
    if type(v) is not dict:
        raise SchemaError('%s: not dict' % path)
    if set(v.keys()) != set(keys):
        raise SchemaError('%s: keys %s != %s' % (path, sorted(v.keys()), sorted(keys)))
    return v


def check_stream(out, req):
    Q = req['banks']
    L = req['lanes']
    R = len(req['borders']) - 1
    chk_dict(out, 'root', ['events', 'final'])
    ev = chk_list(out['events'], 'events')
    if len(ev) != len(req['steps']):
        raise SchemaError('events length')
    for i, e in enumerate(ev):
        p = 'events[%d]' % i
        chk_dict(e, p, ['t', 'update', 'service', 'arrivals', 'sizes'])
        chk_int(e['t'], p + '.t')
        if e['t'] != req['steps'][i]['t']:
            raise SchemaError(p + '.t mismatch')
        if e['update'] is not None:
            u = chk_dict(e['update'], p + '.update', ['borders', 'weights'])
            if len(u['borders']) != R + 1 or len(u['weights']) != R:
                raise SchemaError(p + '.update lengths')
            for j, b in enumerate(u['borders']):
                chk_int(b, p + '.update.borders[%d]' % j)
            for j, w in enumerate(u['weights']):
                chk_int(w, p + '.update.weights[%d]' % j)
        if e['service'] is not None:
            s = chk_dict(e['service'], p + '.service', ['bank', 'packet'])
            chk_int(s['bank'], p + '.service.bank')
            if not (0 <= s['bank'] < Q):
                raise SchemaError('bank range')
            if s['packet'] is not None:
                pk = chk_dict(s['packet'], p + '.packet',
                              ['id', 'rank_error', 'tie_overtakes',
                               'comparable', 'wait'])
                chk_str(pk['id'], p + '.packet.id')
                for f in ('rank_error', 'tie_overtakes', 'comparable', 'wait'):
                    chk_int(pk[f], p + '.packet.' + f)
                    if pk[f] < 0:
                        raise SchemaError('negative ' + f)
        a = chk_list(e['arrivals'], p + '.arrivals')
        exp = sorted(req['steps'][i]['arrivals'], key=lambda z: z['lane'])
        if len(a) != len(exp):
            raise SchemaError(p + '.arrivals len')
        for j, (got, want) in enumerate(zip(a, exp)):
            q = p + '.arrivals[%d]' % j
            chk_dict(got, q, ['id', 'range', 'bank', 'accepted'])
            if got['id'] != want['id']:
                raise SchemaError(q + ' id order (lane sort)')
            chk_int(got['range'], q + '.range')
            chk_int(got['bank'], q + '.bank')
            chk_bool(got['accepted'], q + '.accepted')
            if not (0 <= got['range'] < R):
                raise SchemaError('range bounds')
            if not (0 <= got['bank'] < Q):
                raise SchemaError('bank bounds')
        sz = chk_list(e['sizes'], p + '.sizes')
        if len(sz) != Q:
            raise SchemaError('sizes len')
        for j, v in enumerate(sz):
            chk_int(v, p + '.sizes[%d]' % j)
            if v < 0:
                raise SchemaError('negative size')
    f = chk_dict(out['final'], 'final',
                 ['borders', 'weights', 'histogram', 'rr', 'next_bank',
                  'queues', 'totals'])
    if len(f['borders']) != R + 1:
        raise SchemaError('final borders len')
    if len(f['weights']) != R or len(f['histogram']) != R:
        raise SchemaError('final weights/hist len')
    for v in f['borders'] + f['weights'] + f['histogram']:
        chk_int(v, 'final arrays')
    rr = chk_list(f['rr'], 'final.rr')
    if len(rr) != R:
        raise SchemaError('rr rows')
    for i, row in enumerate(rr):
        chk_list(row, 'rr[%d]' % i)
        if len(row) != L:
            raise SchemaError('rr row len')
        for v in row:
            chk_int(v, 'rr value')
            if not (0 <= v < Q):
                raise SchemaError('rr range')
    chk_int(f['next_bank'], 'next_bank')
    if not (0 <= f['next_bank'] < Q):
        raise SchemaError('next_bank range')
    qs = chk_list(f['queues'], 'queues')
    if len(qs) != Q:
        raise SchemaError('queues len')
    for i, q in enumerate(qs):
        chk_list(q, 'queues[%d]' % i)
        for v in q:
            chk_str(v, 'queue id')
    t = chk_dict(f['totals'], 'totals',
                 ['attempted', 'accepted', 'dropped', 'departed', 'idle',
                  'inversions', 'tie_overtakes', 'comparable', 'wait_sum',
                  'wait_max'])
    for k, v in t.items():
        chk_int(v, 'totals.' + k)
        if v < 0:
            raise SchemaError('negative totals.' + k)


def check_burst(out, req):
    Q = req['banks']
    L = req['lanes']
    R = len(req['borders']) - 1
    N = len(req['packets'])
    chk_dict(out, 'root', ['assignment', 'departures', 'ranges', 'ticks', 'idle'])
    a = chk_list(out['assignment'], 'assignment')
    if len(a) != N:
        raise SchemaError('assignment len')
    for i, e in enumerate(a):
        chk_dict(e, 'assignment[%d]' % i, ['id', 'range', 'bank'])
        chk_str(e['id'], 'a.id')
        chk_int(e['range'], 'a.range')
        chk_int(e['bank'], 'a.bank')
        if e['id'] != req['packets'][i]['id']:
            raise SchemaError('assignment order')
        if not (0 <= e['range'] < R) or not (0 <= e['bank'] < Q):
            raise SchemaError('assignment ranges')
    d = chk_list(out['departures'], 'departures')
    if len(d) != N:
        raise SchemaError('departures len')
    prev = -1
    for i, e in enumerate(d):
        chk_dict(e, 'departures[%d]' % i,
                 ['t', 'bank', 'id', 'rank_error', 'tie_overtakes', 'comparable'])
        for f in ('t', 'bank', 'rank_error', 'tie_overtakes', 'comparable'):
            chk_int(e[f], 'd.' + f)
        chk_str(e['id'], 'd.id')
        if e['t'] <= prev:
            raise SchemaError('departure tick order')
        prev = e['t']
        if not (0 <= e['bank'] < Q):
            raise SchemaError('dep bank range')
    r = chk_list(out['ranges'], 'ranges')
    if len(r) != R:
        raise SchemaError('ranges len')
    for i, e in enumerate(r):
        chk_dict(e, 'ranges[%d]' % i, ['counts', 'bound', 'observed'])
        c = chk_list(e['counts'], 'counts')
        if len(c) != Q:
            raise SchemaError('counts len')
        for v in c:
            chk_int(v, 'counts value')
        chk_int(e['bound'], 'bound')
        chk_int(e['observed'], 'observed')
    chk_int(out['ticks'], 'ticks')
    chk_int(out['idle'], 'idle')
    if sum(len(q) for q in []) != 0:
        pass


def check(out, req):
    if req['mode'] == 'stream':
        check_stream(out, req)
    else:
        check_burst(out, req)
